    int[][] minTime = new int[n][n];

    // Initialize a 2D array to store the number of apples collected on each path
    int[][] numApples = new int[n][n];

    // Initialize the minimum time and number of apples collected on the path from node 0 to node 0
    minTime[0][0] = 0;
    numApples[0][0] = 0;

    // Loop through each edge
    for (int i = 0; i < edges.length; i++) {
        int u = edges[i][0];
        int v = edges[i][1];

        // If the current edge is not a self-loop
        if (u != v) {
            // Update the minimum time and number of apples collected on the path from node u to node v
            minTime[u][v] = Math.min(minTime[u][v], minTime[u][u] + 1);
            numApples[u][v] = numApples[u][u] + (hasApple[v] ? 1 : 0);

            // Update the minimum time and number of apples collected on the path from node v to node u
            minTime[v][u] = Math.min(minTime[v][u], minTime[v][v] + 1);
            numApples[v][u] = numApples[v][v] + (hasApple[u] ? 1 : 0);
        }
    }

    // Initialize the minimum time required to collect all apples and return to node 0
    int minTotalTime = Integer.MAX_VALUE;

    // Loop through each node
    for (int i = 0; i < n; i++) {
        // If the current node has an apple
        if (hasApple[i]) {
            // Update the minimum time required to collect all apples and return to node 0
            minTotalTime = Math.min(minTotalTime, minTime[i][0] + numApples[i][0]);
